class Cat {
    String name;
    static int count = 0;

    Cat(String name) {
        this.name = name;
        count = count + 1;
    }
}

public class Main {
    public static void main(String[] args) {
        Cat a = new Cat("小橘");
        Cat b = new Cat("狸花");
        System.out.println(a.name + " " + b.name + " " + Cat.count);
    }
}
